const AE_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const AE_arrow=(x1,y1,x2,y2,col='#18213A',w=3,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return AE_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const AE_dbl=(x1,y1,x2,y2,col,w=3)=>AE_arrow((x1+x2)/2,(y1+y2)/2,x1,y1,col,w,12)+AE_arrow((x1+x2)/2,(y1+y2)/2,x2,y2,col,w,12);
const AE_C=(x,y,r,fill,st='none',sw=0,ex='')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${st}" stroke-width="${sw}" ${ex}/>`;
const AE_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const AE_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const AE_GREY='#5C6577', AE_STEEL='#495057', AE_DARK='#343A40', AE_LIGHT='#DEE2E6', AE_OIL='#F59F00', AE_OILS='#FFE8CC';
/* a car seen from above-side: body w × h with two wheels */
const AE_car=(x,y,w,col,lab)=>`<rect x="${x}" y="${y}" width="${w}" height="30" rx="8" fill="${col}"/><rect x="${x+w*.3}" y="${y-14}" width="${w*.42}" height="16" rx="6" fill="${col}" fill-opacity=".75"/>`+AE_C(x+w*.22,y+30,8,AE_DARK)+AE_C(x+w*.78,y+30,8,AE_DARK)+(lab?AE_T(x+w/2,y+22,lab,{fs:18,fw:800,a:'middle',fill:'#FFFFFF'}):'');
/* a steering wheel: rim, hub and three spokes, turned by rot degrees */
const AE_wheel=(cx,cy,r,col,rot=0)=>`<g transform="rotate(${rot} ${cx} ${cy})">${AE_C(cx,cy,r,'none',col,r*.16)}${AE_C(cx,cy,r*.22,col)}${AE_L(cx-r*.92,cy,cx+r*.92,cy,col,r*.12)}${AE_L(cx,cy,cx,cy+r*.92,col,r*.12)}</g>`;
/* a spur gear outline: n teeth */
const AE_gear=(cx,cy,r,n,col,fill='#FFFFFF')=>{let p='';for(let k=0;k<n*2;k++){const a=k*Math.PI/n,rr=k%2?r:r*1.14;p+=(k?' L':'M')+(cx+rr*Math.cos(a)).toFixed(1)+','+(cy+rr*Math.sin(a)).toFixed(1)}return `<path d="${p} Z" fill="${fill}" stroke="${col}" stroke-width="4" stroke-linejoin="round"/>`+AE_C(cx,cy,r*.22,col)};
/* cruise-control error on a hill, simulated: e' = −K·Δu + d with Δu = Kp·e (+ Ki·∫e); hill d = 1 from t = 0.5 */
const AE_hill=(ki)=>{let e=0,I=0,out=[];for(let i=0;i<=400;i++){const t=i*.025,d=t>=.5?1:0;const du=1.0*e+ki*I;e+=(-du+d)*.025;I+=e*.025;if(i%8===0)out.push([t,e])}return out};
const AE_P=AE_hill(0), AE_PIr=AE_hill(.8);

