 const row=(yy,v,d)=>AE_car(30,yy,70,BLU)+AE_car(104+d*k+6,yy,70,AE_GREY)+AE_dbl(104,yy+14,104+d*k,yy+14,GRN,4)+AE_T(104+d*k/2,yy-10,d+' m',{fs:24,fw:800,a:'middle',fill:GRN})+AE_T(65,yy+70,v,{fs:22,fw:700,a:'middle',fill:AE_GREY});
