  AE_T(X(.53),Y(.45),'flare:',{fs:22,fw:800,a:'middle',fill:ORG})+AE_T(X(.53),Y(.45)+28,'no load',{fs:22,fw:800,a:'middle',fill:ORG})+AE_T(X(.98),Y(.9)-12,'on-coming, late',{fs:22,fw:800,a:'end',fill:GRN});
