function EXTRA(R,ICON){
 /* hook pictures: each a 320 × 130 card inside the mint disc */
 const card=(x,y,col,body)=>`<g transform="translate(${x-160} ${y-65})">${AE_box(0,0,320,130,{fill:'#FFFFFF',st:col,sw:3,r:18})}${body}</g>`;
 ICON.aeHkGear=(x,y)=>{const cx=70,cy=78,r=48,a=t=>Math.PI*(1.15-t*1.3);
  let tk='';for(let k=0;k<=6;k++){const q=a(k/6);tk+=AE_L((cx+r*Math.cos(q)).toFixed(1),(cy-r*Math.sin(q)).toFixed(1),(cx+(r-9)*Math.cos(q)).toFixed(1),(cy-(r-9)*Math.sin(q)).toFixed(1),AE_DARK,3)}
  const n1=a(1300/3000),n2=a(1857/3000);
  return card(x,y,BLU,`<path d="M${(cx+r*Math.cos(a(0))).toFixed(1)},${(cy-r*Math.sin(a(0))).toFixed(1)} A${r},${r} 0 1 1 ${(cx+r*Math.cos(a(1))).toFixed(1)},${(cy-r*Math.sin(a(1))).toFixed(1)}" fill="none" stroke="${AE_STEEL}" stroke-width="4"/>${tk}
   ${AE_L(cx,cy,(cx+40*Math.cos(n1)).toFixed(1),(cy-40*Math.sin(n1)).toFixed(1),AE_GREY,4,'stroke-dasharray="5 4"')}${AE_L(cx,cy,(cx+40*Math.cos(n2)).toFixed(1),(cy-40*Math.sin(n2)).toFixed(1),RED,5)}${AE_C(cx,cy,6,AE_DARK)}
   ${AE_T(140,56,'kickdown',{fs:26,fw:800,fill:BLU})}${AE_T(140,92,'1300 → 1857 rpm',{fs:20,fw:700,fill:AE_GREY})}`)};
 ICON.aeHkGap=(x,y)=>card(x,y,ORG,`${AE_L(16,104,304,104,AE_GREY,3)}<polygon points="96,70 238,52 238,92" fill="${ORG}" fill-opacity=".25"/>${AE_car(20,62,76,BLU)}${AE_car(236,62,70,GRN)}
   ${AE_dbl(98,30,234,30,ORG,3)}${AE_T(166,22,'time gap',{fs:20,fw:800,a:'middle',fill:ORG})}`);
 ICON.aeHkWheel=(x,y)=>card(x,y,MAG,`${AE_wheel(70,66,44,AE_STEEL,-25)}${AE_arrow(128,40,128,92,MAG,4,12)}${AE_T(150,56,'parking:',{fs:26,fw:800,fill:MAG})}${AE_T(150,92,'big assist',{fs:22,fw:700,fill:AE_GREY})}`);
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.aeRcMap=(x,y)=>{const mx=v=>60+v/120*340,my=a=>290-a/100*250;
  let s=AE_L(60,290,410,290,AE_DARK,3)+AE_L(60,290,60,30,AE_DARK,3)+AE_T(70,40,'throttle',{fs:22,fw:700,fill:AE_GREY})+AE_T(405,280,'speed',{fs:22,fw:700,a:'end',fill:AE_GREY});
  s+=AE_L(mx(40),my(0),mx(100),my(100),BLU,5)+AE_L(mx(30),my(0),mx(80),my(100),GRN,5,'stroke-dasharray="10 7"');
  s+=AE_arrow(mx(60),my(30)-8,mx(60),my(90)+14,ORG,4,14)+AE_C(mx(60),my(30),9,BLU)+AE_C(mx(60),my(90),9,GRN)+AE_T(mx(60)+16,my(30)+8,'top gear',{fs:22,fw:800,fill:BLU})+AE_T(mx(60)-16,my(90)+8,'kickdown',{fs:22,fw:800,a:'end',fill:GRN});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
 ICON.aeRcGap=(x,y)=>{const k=6;let s='';
  [[60,'25 m/s',50],[200,'20 m/s',40]].forEach(([yy,v,d])=>{s+=AE_car(10,yy,60,BLU)+AE_car(74+d*k+4,yy,60,AE_GREY)+AE_dbl(74,yy+14,74+d*k,yy+14,ORG,4)+AE_T(74+d*k/2,yy-12,d+' m',{fs:26,fw:800,a:'middle',fill:ORG})+AE_T(40,yy+72,v,{fs:22,fw:700,a:'middle',fill:AE_GREY})});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
 ICON.aeRcAssist=(x,y)=>{const bh=v=>v/40*220;let s=AE_L(20,280,400,280,AE_DARK,3);
  [['parking',40,GRN,60],['120 km/h',4,BLU,250]].forEach(([n,v,col,x0])=>{s+=`<rect x="${x0}" y="${280-bh(v)}" width="110" height="${bh(v)}" rx="6" fill="${col}" fill-opacity=".85"/>`+AE_T(x0+55,270-bh(v),v+' N·m',{fs:26,fw:800,a:'middle',fill:col})+AE_T(x0+55,312,n,{fs:24,fw:800,a:'middle',fill:AE_DARK})});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
}
